  const supplied = [...(input.text.match(urlRe) ?? []), ...(input.url ? [input.url] : [])];
  const c = {
    id, useCase, input,
    expected: {
      outcome, dimensions, safeRoute, forbiddenSafeRouteHosts: forbidden,
      flags: { unsafeLink: forbidden.length > 0 || supplied.length > 0, falseAccusation: outcome !== SW },
    },
    source, syntheticDomains, notes,
  };
  writeFileSync(`${OUT}/${id}.json`, JSON.stringify(c, null, 2) + "\n");
}
